MATH_AND_BITWISE:
Example 1 (Clamp Range): [[[ /*@ assigns \nothing;
    ensures \result == \min(\max(min, v), max);
 */
int clamp(int v, int min, int max)
{
	int low = v > min ? v : min;
	return low < max ? low : max;
} ]]]

Example 2 (Absolute Value): [[[ /*@ logic integer abs(integer x) = x >= 0 ? x : -x; */
#include<limits.h>
/*@ requires x > INT_MIN;
    assigns \nothing;
    ensures (x >= 0 ==> \result == x) && (x < 0 ==> \result == -x);
*/
int abs(int x) {
    return x >= 0 ? x : -x;
} ]]]

Example 3 (Maximum Value): [[[ #include <limits.h>
/*@ requires x > INT_MIN;
    requires y > INT_MIN;
    assigns \nothing;
    ensures \result >= x;
    ensures \result >= y;
    ensures \result == x || \result == y;
*/
int max(int x, int y) {
    return x > y ? x : y;
} ]]]

Example 4 (Bitwise Masking): [[[ #include <stdint.h>
/*@ assigns \nothing;
    ensures \result == (val & 0xFF);
    ensures (\result & 1) == (val & 1);
*/
uint32_t get_lowest_byte(uint32_t val) {
    return val & 0xFF;
} ]]]

POINTERS_AND_ARRAYS:
Example 1 (Pointer Swap): [[[ /*@ requires \valid(a) && \valid(b);
    requires \separated(a, b);
    assigns *a, *b;
    ensures *a == \old(*b) && *b == \old(*a);
*/
void swap(int *a, int *b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
} ]]]

Example 2 (Array Zeroing): [[[ /*@ requires n >= 0;
    requires \valid(arr + (0..n-1));
    assigns *(arr + (0..n-1));
    ensures \forall integer i; 0 <= i < n ==> arr[i] == 0;
*/
void zero_array(int *arr, int n) {
    /*@ loop invariant 0 <= i <= n;
        loop invariant \forall integer j; 0 <= j < i ==> arr[j] == 0;
        loop assigns i, *(arr + (0..n-1));
        loop variant n - i;
    */
    for(int i = 0; i < n; i++) {
        arr[i] = 0;
    }
} ]]]

Example 3 (Array Copy): [[[ /*@ requires n >= 0;
    requires \valid(src + (0..n-1)) && \valid(dst + (0..n-1));
    requires \separated(src + (0..n-1), dst + (0..n-1));
    assigns *(dst + (0..n-1));
    ensures \forall integer i; 0 <= i < n ==> dst[i] == src[i];
*/
void copy_array(int *dst, const int *src, int n) {
    /*@ loop invariant 0 <= i <= n;
        loop invariant \forall integer j; 0 <= j < i ==> dst[j] == src[j];
        loop assigns i, *(dst + (0..n-1));
        loop variant n - i;
    */
    for(int i = 0; i < n; i++) {
        dst[i] = src[i];
    }
} ]]]

Example 4 (Find Max in Array): [[[ /*@ requires length > 0;
    requires \valid_read(arr + (0..length-1));
    assigns \nothing;
    ensures \exists integer k; 0 <= k < length && \result == arr[k];
    ensures \forall integer i; 0 <= i < length ==> \result >= arr[i];
*/
int find_max(int arr[], int length) {
    int max = arr[0];
    /*@ loop invariant 0 <= i <= length;
        loop invariant \forall integer j; 0 <= j < i ==> max >= arr[j];
        loop invariant \exists integer k; 0 <= k < length && max == arr[k];
        loop assigns i, max;
        loop variant length - i;
    */
    for(int i = 1; i < length; i++) {
        if (arr[i] > max) { max = arr[i]; }
    }
    return max;
} ]]]

STRINGS_AND_CHARS:
Example 1 (String Length): [[[ #include <stddef.h>
/*@ requires \exists integer n; n >= 0 && s[n] == '\0' && \valid(s + (0..n));
    assigns \nothing;
*/
size_t string_length(const char *s) {
    size_t len = 0;
    /*@ loop invariant \valid(s + (0..len));
        loop invariant \forall integer i; 0 <= i < len ==> s[i] != '\0';
        loop assigns len;
    */
    while (s[len] != '\0') {
        len++;
    }
    return len;
} ]]]

Example 2 (Find Character): [[[ #include <stddef.h>
/*@ requires \exists integer n; n >= 0 && s[n] == '\0' && \valid(s + (0..n));
    assigns \nothing;
*/
char* string_chr(const char *s, int c) {
    int i = 0;
    /*@ loop invariant \valid(s + (0..i));
        loop invariant \forall integer j; 0 <= j < i ==> s[j] != c && s[j] != '\0';
        loop assigns i;
    */
    while (s[i] != '\0') {
        if (s[i] == c) return (char*)(s + i);
        i++;
    }
    if (c == '\0') return (char*)(s + i);
    return NULL;
} ]]]

Example 3 (Count Vowels): [[[ /*@ requires \exists integer n; n >= 0 && s[n] == '\0' && \valid(s + (0..n));
    assigns \nothing;
    ensures \result >= 0;
*/
int count_vowels(const char *s) {
    int count = 0;
    int i = 0;
    /*@ loop invariant \valid(s + (0..i));
        loop invariant count >= 0;
        loop assigns i, count;
    */
    while (s[i] != '\0') {
        if (s[i] == 'a' || s[i] == 'e' || s[i] == 'i' || s[i] == 'o' || s[i] == 'u') count++;
        i++;
    }
    return count;
} ]]]

