RECURSION_AND_TREES:
Example 1 (Recursive Countdown): [[[ /*@ requires n >= 0;
    decreases n;
    assigns \nothing;
    ensures \result == 0;
*/
int recursive_countdown(int n) {
    if (n == 0) return 0;
    return recursive_countdown(n - 1);
} ]]]

Example 2 (Recursive Factorial): [[[ /*@ logic integer factorial(integer n) = (n <= 0) ? 1 : n * factorial(n - 1); */
/*@ requires 0 <= n <= 12;
    decreases n;
    assigns \nothing;
    ensures \result == factorial(n);
*/
int fact(int n) {
    if (n == 0) return 1;
    return n * fact(n - 1);
} ]]]

Example 3 (Recursive Sum): [[[ /*@ logic integer sum(integer n) = (n <= 0) ? 0 : n + sum(n - 1); */
/*@ requires n >= 0;
    decreases n;
    assigns \nothing;
    ensures \result == sum(n);
*/
int recursive_sum(int n) {
    if (n == 0) return 0;
    return n + recursive_sum(n - 1);
} ]]]

Example 4 (Tree Node Count): [[[ #include <stddef.h>
typedef struct Node { int data; struct Node *left; struct Node *right; } Node;
/*@ requires \valid(node) || node == \null;
    decreases depth;
    assigns \nothing;
    ensures \result >= 0;
*/
int count_nodes(Node *node, int depth) {
    if (node == NULL || depth <= 0) return 0;
    return 1 + count_nodes(node->left, depth - 1) + count_nodes(node->right, depth - 1);
} ]]]

